```python
class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [0] * n

        for i in range(n):
            val = nums[i]
            if val == 0:
                result[i] = val
            elif val > 0:
                # Move val steps to the right in circular array
                result[i] = (i + val) % n
            elif val < 0:
                # Move abs(val) steps to the left in circular array
                result[i] = (i - abs(val)) % n

        return result
```

